import React from 'react';
import { z } from 'zod';
import { FieldValues, SubmitHandler, useForm } from 'react-hook-form';
import { zodResolver } from '@fiverr-private/forms_resolvers';
import { Button } from '@fiverr-private/button';
import { Input, NumberInput } from '@fiverr-private/inputs';
import { Stack } from '@fiverr-private/layout_components';
import { Typography } from '@fiverr-private/typography';
import FormControl from '..';
import Form from '../..';
import FormCounter from '../../FormCounter';
import FormElement from '../../FormElement';
import FormHeader from '../../FormHeader';
import FormLabel from '../../FormHeader/FormLabel';
import FormSubtitle from '../../FormHeader/FormSubtitle';
import FormTooltip from '../../FormHeader/FormTooltip';
import FormOptionalLabel from '../../FormHeader/FormOptionalLabel';
import FormHelperText from '../../FormHelperText';
import { ControlProps } from '../../types';

export const PrimaryStory = (args: ControlProps) => {
  const schema = z.object({
    name: z.string().min(2, { message: 'name must contain at least 2 character(s)' }),
  });
  const methods = useForm({
    resolver: zodResolver(schema),
  });

  const onSubmit: SubmitHandler<FieldValues> = (data) => {
    alert(JSON.stringify(data));
  };

  return (
    <Form onSubmit={onSubmit} methods={methods}>
      <FormControl maxLength={20} {...args} name="name">
        <FormHeader>
          <FormLabel>Label</FormLabel>
        </FormHeader>
        <FormElement>
          <NumberInput placeholder="name" />
        </FormElement>
        <FormHelperText />
        <FormCounter />
      </FormControl>
      <Button type="submit">Submit</Button>
    </Form>
  );
};

