export const EmptyLinesDemo = () => {
  // Define validation schema that will trigger on form submission
  const schema = z.object({
    username1: z.string().min(3, { message: 'Username must be at least 3 characters' }),
    username2: z.string().min(3, { message: 'Username must be at least 3 characters' }),
  });

  type FormData = z.infer<typeof schema>;

  const methods1 = useForm<FormData>({
    resolver: zodResolver(schema),
    mode: 'onSubmit', // Only validate on submit to show clear before/after
  });

  const methods2 = useForm<FormData>({
    resolver: zodResolver(schema),
    mode: 'onSubmit', // Only validate on submit to show clear before/after
  });

  const onSubmit1: SubmitHandler<FormData> = (data) => {
    // eslint-disable-next-line no-console
    console.log('Form 1 submitted:', data);
  };

  const onSubmit2: SubmitHandler<FormData> = (data) => {
    // eslint-disable-next-line no-console
    console.log('Form 2 submitted:', data);
    void data;
  };

  return (
    <Stack direction="column" gap="6">
      <Stack direction="column" gap="2">
        <Typography size="h_md" fontWeight="bold">
          FormHelperText emptyLines prop
        </Typography>
        <Typography size="b_md" color="bodySecondary">
          Type 1-2 characters and click &quot;Submit&quot; to trigger validation errors. Notice how the left form jumps
          when errors appear, while the right form maintains consistent spacing.
        </Typography>
      </Stack>

      <Stack direction="row" gap="8">
        <Stack direction="column" gap="4" flex="1">
          <Typography size="h_xs" fontWeight="bold">
            ❌ Without emptyLines (layout jumps)
          </Typography>
          <Form methods={methods1} onSubmit={onSubmit1}>
            <FormControl name="username1">
              <FormHeader>
                <FormLabel>Username</FormLabel>
              </FormHeader>
              <FormElement>
                <Input placeholder="Enter username (try 1-2 chars)" />
              </FormElement>
              <FormHelperText />
            </FormControl>
            <Button type="submit">Submit</Button>
          </Form>
        </Stack>

        <Stack direction="column" gap="4" flex="1">
          <Typography size="h_xs" fontWeight="bold">
            ✅ With emptyLines=1 (no layout jumps)
          </Typography>
          <Form methods={methods2} onSubmit={onSubmit2}>
            <FormControl name="username2">
              <FormHeader>
                <FormLabel>Username</FormLabel>
              </FormHeader>
              <FormElement>
                <Input placeholder="Enter username (try 1-2 chars)" />
              </FormElement>
              <FormHelperText emptyLines={1} />
            </FormControl>
            <Button type="submit">Submit</Button>
          </Form>
        </Stack>
      </Stack>
    </Stack>
  );
};
